import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import org.joda.time.base.AbstractPartial;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.AbstractPartialFieldProperty;
import org.joda.time.field.DateTimeFieldType;
import org.joda.time.field.DurationFieldType;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormat;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Partial_with_TriageGen2Test {

    @Test(expected = IllegalArgumentException.class)
    public void testWith_NullFieldType_ThrowsException() {
        Partial partial = new Partial(ISOChronology.getInstanceUTC());
        partial.with(null, 1);
    }

    @Test
    public void testWith_ExistingField_UpdateValue() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOf();
        Partial partial = new Partial(new DateTimeFieldType[]{yearType}, new int[]{2020}, ISOChronology.getInstanceUTC());

        // Test updating value
        Partial updated = partial.with(yearType, 2021);

        assertEquals(1, updated.size());
        assertEquals(2021, updated.getValues()[0]);
        assertNotSame(partial, updated);
    }

    @Test
    public void testWith_ExistingField_SameValue_ReturnsThis() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOf();
        Partial partial = new Partial(new DateTimeFieldType[]{yearType}, new int[]{2020}, ISOChronology.getInstanceUTC());

        // Test that if value is same, it returns 'this'
        Partial result = partial.with(yearType, 2020);

        assertSame(partial, result);
    }

    @Test
    public void testWith_NewField_InsertAtStart() {
        // We want to insert a field that has a larger unit than the existing one
        // to trigger the sorting logic.
        DateTimeFieldType monthType = DateTimeFieldType.monthOfYear();
        DateTimeFieldType yearType = DateTimeFieldType.yearOf();

        // Start with Year (larger unit)
        Partial partial = new Partial(new DateTimeFieldType[]{yearType}, new int[]{2020}, ISOChronology.getInstanceUTC());

        // Add Month (smaller unit). In the code: unitField.compareTo(loopUnitField) > 0 breaks.
        // Month unit is smaller than Year unit. 
        // If Month unit < Year unit, compare > 0 is false.
        // If Month unit > Year unit, compare > 0 is true.
        // Note: Joda's compareTo for DurationField usually means larger duration is "greater".
        // Year is larger than Month.

        Partial updated = partial.with(monthType, 12);

        assertEquals(2, updated.size());
        // Verify order: The loop breaks when unitField.compareTo(loopUnitField) > 0.
        // If Month is inserted, and it's smaller than Year, it should go after Year or based on logic.
        // Let's check if it contains both.
        boolean hasYear = false;
        boolean hasMonth = false;
        for (int i = 0; i < updated.size(); i++) {
            if (updated.getFieldType(i).equals(yearType)) hasYear = true;
            if (updated.getFieldType(i).equals(monthType)) hasMonth = true;
        }
        assertTrue(hasYear);
        assertTrue(hasMonth);
    }

    @Test
    public void testWith_NewField_InsertMiddleByRange() {
        // This tests the branch: else if (compare == 0) { rangeField.compareTo(loopRangeField) > 0 }
        // This is harder to trigger without custom DateTimeFieldTypes, 
        // but we can test the general insertion logic.

        DateTimeFieldType type1 = DateTimeFieldType.yearOf();
        DateTimeFieldType type2 = DateTimeFieldType.monthOfYear();
        DateTimeFieldType type3 = DateTimeFieldType.dayOfMonth();

        Partial partial = new Partial(new DateTimeFieldType[]{type1, type3}, new int[]{2020, 1}, ISOChronology.getInstanceUTC());

        // Insert month in the middle
        Partial updated = partial.with(type2, 5);

        assertEquals(3, updated.size());
        int[] values = updated.getValues();
        // Since Month is between Year and Day in scale
        // The loop will find i=0 (Year), compare Month to Year -> Month < Year -> continue
        // i=1 (Day), compare Month to Day -> Month > Day -> break
        // Result: i=1. New array: [Year, Month, Day]
        assertEquals(2020, values[0]);
        assertEquals(5, values[1]);
        assertEquals(1, values[2]);
    }

    @Test
    public void testWith_NewField_UnitNotSupported() {
        // If unitField.isSupported() is false, it should just append at the end (i = iTypes.length)
        // Most standard types are supported, but we can simulate by having an empty partial
        Partial partial = new Partial(ISOChronology.getInstanceUTC());
        DateTimeFieldType type = DateTimeFieldType.yearOf();

        Partial updated = partial.with(type, 2023);

        assertEquals(1, updated.size());
        assertEquals(2023, updated.getValues()[0]);
    }

    @Test
    public void testWith_NewField_LargeUnitFirst() {
        // Ensure that a very large unit is placed at the beginning
        DateTimeFieldType year = DateTimeFieldType.yearOf();
        DateTimeFieldType month = DateTimeFieldType.monthOfYear();

        Partial partial = new Partial(new DateTimeFieldType[]{month}, new int[]{1}, ISOChronology.getInstanceUTC());
        // Year is larger than Month. unitField(Year).compareTo(loopField(Month)) will be > 0.
        // Loop breaks at i=0.
        Partial updated = partial.with(year, 2023);

        assertEquals(0, updated.getFieldType(0).compareTo(month) > 0 ? 0 : 1); // Check order logic via index
        // Based on code: i=0, newTypes[0]=year, newTypes[1]=month
        assertEquals(year, updated.getFieldType(0));
        assertEquals(month, updated.getFieldType(1));
    }
}
